const body = $input.first().json.body || {};
const raw = String(body.date || '').trim();
const m = raw.match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/);

const now = new Date();
const start = m
  ? new Date(Number(m[1]), Number(m[2]) - 1, Number(m[3]))
  : new Date(now.getFullYear(), now.getMonth(), now.getDate());
start.setHours(0, 0, 0, 0);

const end = new Date(start);
end.setDate(end.getDate() + 1);

const label = start.toLocaleDateString('en-GB', { weekday: 'long', day: 'numeric', month: 'long' });
return [{ json: { date: raw || 'today', label, resolved: !!m,
                  timeMin: start.toISOString(), timeMax: end.toISOString() } }];

const meta = $('Day range').first().json;
const events = $input.all()
  .filter(i => i.json && (i.json.summary || i.json.start))
  .map(i => {
    const e = i.json;
    const when = e.start?.dateTime
      ? new Date(e.start.dateTime).toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit' })
      : 'all day';
    return `${when} ${e.summary || '(untitled)'}`;
  });
return [{ json: { date: meta.date, day: meta.label, count: events.length, events } }];
